import React from 'react';
import { describe, it, expect, vi, beforeEach } from 'vitest';
import { render, screen, fireEvent, act } from '@testing-library/react';
import HomePage from '@/app/(dashboard)/home/page';
import { useExecutionStore } from '@/lib/store';
import { templates } from '@/lib/templates';
import type { Execution } from '@/types';

const nav = vi.hoisted(() => ({ params: new URLSearchParams() }));
vi.mock('next/navigation', () => ({ useSearchParams: () => nav.params }));
vi.mock('@/lib/i18n', () => ({ useLanguage: () => ({ language: 'en', t: (s: string) => s }) }));
vi.mock('@/lib/analytics', () => ({ trackEvent: vi.fn() }));
vi.mock('@/components/Settings', () => ({ useSettings: () => ({ settings: { providers: {} } }) }));
vi.mock('@/lib/hooks/useExecute', () => ({ useProviders: () => ({ providers: [], anyConfigured: false, fetchProviders: vi.fn() }) }));
vi.mock('@/components/home/HomeBrowseExperience', () => ({ HomeBrowseExperience: () => <div>local-browse</div> }));
vi.mock('@/components', () => ({
    ResultViewer: (p: { execution: Execution; output: string; evidenceReceipt?: unknown; onAccept: () => void; onFollowUp: (s: string) => void }) => <section>
        <div data-testid="local-identity">{p.execution.id}|{p.output}|{p.execution.intent}</div>
        <div data-testid="local-receipt">{p.evidenceReceipt === undefined ? 'absent' : 'fabricated'}</div>
        <button onClick={p.onAccept}>local-accept</button>
        <button onClick={() => p.onFollowUp('local refinement')}>local-refine</button>
    </section>,
    ProcessingScreen: (p: { onComplete: (s: string) => void }) => <button onClick={() => p.onComplete('LOCAL_CHILD_OUTPUT')}>local-complete</button>,
    TemplatePreviewModal: () => null,
    OnboardingTour: () => null,
}));
const template = templates.find(t => !t.isFolder && t.id === 'documentation')!;
function make(id: string): Execution {
    return { id, templateId: template.id, templateName: template.name, category: template.category,
        input: { topic: id + '_topic', audience: id + '_audience' }, intent: id + '_intent', output: id + '_output',
        status: 'completed', result: id === 'LOCAL_A' ? 'accepted' : 'rejected', createdAt: new Date('2026-10-11T00:00:00Z'),
        threadId: id + '_thread', rootExecutionId: id + '_root', projectLabel: id + '_project', knowledgeCollectionId: id + '_knowledge',
        evidenceReceiptSnapshot: { receiptId: id + '_lightweight', decision: 'ALLOW' } };
}
function arrange() {
    const a = make('LOCAL_A'), b = make('LOCAL_B'), c = make('LOCAL_C');
    expect(a).not.toBe(b); expect(a.input).not.toBe(b.input);
    const before = [a, b, c].map(x => structuredClone(x));
    useExecutionStore.setState({ executions: [a, b, c], currentExecution: b });
    nav.params = new URLSearchParams('continue=LOCAL_A');
    return { a, b, c, before };
}
const get = (id: string) => useExecutionStore.getState().getExecutionById(id);
beforeEach(() => { localStorage.clear(); nav.params = new URLSearchParams(); useExecutionStore.setState({ executions: [], currentExecution: null }); });
describe('Distinct Local actual-Home consumer challenges', () => {
    it('confirms currentExecution is persisted by the actual unchanged store', () => {
        const { b } = arrange();
        const saved = JSON.parse(localStorage.getItem('cvf-executions-storage')!);
        expect(saved.state.currentExecution.id).toBe(b.id);
        expect(saved.state.executions.map((e: Execution) => e.id)).toEqual(['LOCAL_A', 'LOCAL_B', 'LOCAL_C']);
    });
    it('accepts displayed historical A under ambient C without fabricated receipt or sibling mutation', () => {
        const { c, before } = arrange(); render(<HomePage />);
        act(() => useExecutionStore.getState().setCurrentExecution(c));
        expect(screen.getByTestId('local-identity').textContent).toBe('LOCAL_A|LOCAL_A_output|LOCAL_A_intent');
        expect(screen.getByTestId('local-receipt').textContent).toBe('absent');
        fireEvent.click(screen.getByRole('button', { name: 'local-accept' }));
        expect(screen.getByText('local-browse')).toBeTruthy();
        expect(get('LOCAL_A')?.result).toBe('accepted');
        expect(get('LOCAL_B')).toEqual(before[1]); expect(get('LOCAL_C')).toEqual(before[2]);
    });
    it('derives child input and lineage from displayed A and completes that child under ambient C', () => {
        const { c, before } = arrange(); render(<HomePage />);
        fireEvent.click(screen.getByRole('button', { name: 'local-refine' }));
        const child = useExecutionStore.getState().executions[0];
        expect(child.parentExecutionId).toBe('LOCAL_A');
        expect(child.input).toEqual({ ...before[0].input, _previousOutput: 'LOCAL_A_output' });
        expect([child.threadId, child.rootExecutionId, child.projectLabel, child.knowledgeCollectionId]).toEqual(['LOCAL_A_thread', 'LOCAL_A_root', 'LOCAL_A_project', 'LOCAL_A_knowledge']);
        act(() => useExecutionStore.getState().setCurrentExecution(c));
        fireEvent.click(screen.getByRole('button', { name: 'local-complete' }));
        expect(get(child.id)?.output).toBe('LOCAL_CHILD_OUTPUT');
        expect(screen.getByTestId('local-identity').textContent).toBe(child.id + '|LOCAL_CHILD_OUTPUT|local refinement');
        expect(screen.getByTestId('local-receipt').textContent).toBe('absent');
        expect([get('LOCAL_A'), get('LOCAL_B'), get('LOCAL_C')]).toEqual(before);
    });
});

